  // Feature: Station
  'feature.station.tag': 'Stationsserver',
  'feature.station.title': 'Din enhet blir gemenskapsinfrastruktur',
  'feature.station.desc': 'Din telefon kan vara en server. Din dator kan vara en server. Den där gamla Raspberry Pi som samlar damm kan vara en server. Geogram kör stationsprogramvara på vilken enhet som helst och förvandlar personlig hårdvara till gemenskapsinfrastruktur. Inget lever på någon annans moln.',
  'feature.station.list1': 'Servera innehåll till webbläsare via WiFi eller internet',
