  // Apps section
  'apps.title': 'Appar för gemenskapskoordinering',
  'apps.subtitle': 'En svit av appar designade för informationsdelning och koordinering. Varje lagrar data i läsbara format som synkroniseras mellan enheter via vilken tillgänglig transport som helst.',
  'apps.chat.title': 'Chatt',
  'apps.chat.desc': 'Realtidsmeddelanden med rumsbaserade kanaler och direktmeddelanden. Stöder filbilagor, röstmeddelanden, platsdelning och omröstningar. Fungerar med alla anslutningstyper.',
  'apps.blog.title': 'Blogg',
  'apps.blog.desc': 'Långformspublicering med markdown-innehåll, utkast, taggar och kommentarer. Skapa lokal journalistik och gemenskapsnyhetsbrev som fungerar helt offline.',
  'apps.work.title': 'Arbete',
  'apps.work.desc': 'Offline Google Docs-alternativ. Kalkylblad, dokument, presentationer och formulär med realtidssamarbete när ansluten.',
  'apps.events.title': 'Evenemang',
  'apps.events.desc': 'Gemenskapskalendrar med evenemangsdetaljer, platser, mediagallerier och deltagarspårning. Perfekt för att organisera sammankomster och hjälpdistributioner.',
  'apps.places.title': 'Platser',
  'apps.places.desc': 'Geografiska intressepunkter med beskrivningar och foton. Dokumentera vattenkällor, skydd, förråd eller faror utan kommersiella karttjänster.',
  'apps.alerts.title': 'Varningar',
